<?phpif (!current_user_can('manage_options')) {    return;}$message = '';$social_media_options = get_option('_shw_social_media_website', []);// Process form submissionif ($_SERVER['REQUEST_METHOD'] === 'POST' && isset($_POST['submit'])) {    if (        !isset($_POST['_nonce_social_media']) ||        !wp_verify_nonce(            $_POST['_nonce_social_media'],            '_nonce_social_media'        )    ) {        $message = '            <div class="alert alert-danger alert-dismissible fade show" role="alert">                Security validation failed!                <button type="button" class="btn-close" data-bs-dismiss="alert"></button>            </div>        ';    } else {        $social_data = [            'telegram'  => sanitize_text_field($_POST['telegram-f'] ?? ''),            'instagram' => sanitize_text_field($_POST['instagram-f'] ?? ''),            'whatsapp'  => sanitize_text_field($_POST['whatsapp-f'] ?? ''),            'discord'   => sanitize_text_field($_POST['discord-f'] ?? ''),            'linkedin'  => sanitize_text_field($_POST['linkedin-f'] ?? ''),            'youtube'   => sanitize_text_field($_POST['youtube-f'] ?? ''),            'x'         => sanitize_text_field($_POST['x-f'] ?? ''),        ];        update_option('_shw_social_media_website', $social_data);        $social_media_options = $social_data;        $message = '            <div class="alert alert-success alert-dismissible fade show" role="alert">                Settings saved successfully!                <button type="button" class="btn-close" data-bs-dismiss="alert"></button>            </div>        ';    }}?><style>    /* Full Width Admin Page */    .tns-social-settings {        width: 100% !important;        max-width: none !important;        margin: 0 !important;        padding: 0 20px 30px 0 !important;        box-sizing: border-box !important;    }    .tns-social-settings .tns-social-card {        width: 100% !important;        max-width: none !important;        box-sizing: border-box !important;    }    .tns-social-settings .tns-social-card .card-body {        width: 100%;        box-sizing: border-box;    }    .tns-social-settings .tns-social-card form {        width: 100%;    }    .tns-social-settings .tns-social-card .row {        width: 100%;        margin-left: 0;        margin-right: 0;    }    .tns-social-settings .tns-social-card .col-12 {        padding-left: 12px;        padding-right: 12px;    }    .tns-social-settings .form-control {        width: 100%;    }</style><div class="tns-social-settings">    <!-- Page Header -->    <div class="d-flex justify-content-between align-items-center mb-4">        <div>            <h4 class="mb-1">                <?php echo esc_html(get_admin_page_title()); ?>            </h4>            <p class="text-muted mb-0">                Manage your website's social media links.            </p>        </div>    </div>    <!-- Message -->    <?php if (!empty($message)) : ?>        <?php echo $message; ?>    <?php endif; ?>    <!-- Main Card -->    <div class="card border-0 shadow-sm tns-social-card">        <!-- Card Header -->        <div class="card-header bg-white border-bottom py-3">            <h5 class="mb-0">                Social Media Settings            </h5>        </div>        <!-- Card Body -->        <div class="card-body p-4">            <form method="post">                <div class="row g-4">                    <?php                    $fields = [                        'telegram' => [                            'Telegram',                            'telegram',                            'Enter your Telegram ID or URL'                        ],                        'instagram' => [                            'Instagram',                            'instagram',                            'Enter your Instagram ID or URL'                        ],                        'whatsapp' => [                            'WhatsApp',                            'whatsapp',                            'Enter your WhatsApp ID or URL'                        ],                        'discord' => [                            'Discord',                            'discord',                            'Enter your Discord ID or URL'                        ],                        'linkedin' => [                            'LinkedIn',                            'linkedin',                            'Enter your LinkedIn ID or URL'                        ],                        'youtube' => [                            'YouTube',                            'youtube',                            'Enter your YouTube ID or URL'                        ],                        'x' => [                            'X',                            'x',                            'Enter your X ID or URL'                        ],                    ];                    foreach ($fields as $key => [$label, $icon, $tooltip]) :                        ?>                        <div class="col-12 col-md-6">                            <label                                    for="<?php echo esc_attr($key); ?>-f"                                    class="form-label fw-semibold"                            >                                <?php echo esc_html($label); ?>                            </label>                            <div class="input-group">                                <span class="input-group-text bg-light">                                    <span                                            uk-icon="icon: <?php echo esc_attr($icon); ?>"                                    ></span>                                </span>                                <input                                        class="form-control"                                        id="<?php echo esc_attr($key); ?>-f"                                        name="<?php echo esc_attr($key); ?>-f"                                        type="text"                                        value="<?php echo esc_attr(                                            $social_media_options[$key] ?? ''                                        ); ?>"                                        placeholder="<?php echo esc_attr($tooltip); ?>"                                >                            </div>                            <div class="form-text">                                <?php echo esc_html($tooltip); ?>                            </div>                        </div>                    <?php endforeach; ?>                </div>                <!-- Save -->                <div class="mt-4 pt-3 border-top">                    <?php                    wp_nonce_field(                        '_nonce_social_media',                        '_nonce_social_media'                    );                    ?>                    <button                            type="submit"                            name="submit"                            class="btn btn-primary px-4"                    >                        <i class="fas fa-save me-2"></i>                        Save Settings                    </button>                </div>            </form>        </div>    </div></div>